<?php declare(strict_types=1);namespace App\Infrastructure\Persistence\Doctrine\Arena;use App\Domain\Arena\Repository\ArenaPerformanceRecorderInterface;use App\Infrastructure\Persistence\Doctrine\Arena\Entity\DuelAnswerRecord;use App\Infrastructure\Persistence\Doctrine\Arena\Entity\DuelQuestionRecord;use App\Infrastructure\Persistence\Doctrine\Performance\Entity\AnswerRecord;use App\Infrastructure\Persistence\Doctrine\Performance\Entity\AttemptRecord;use Doctrine\ORM\EntityManagerInterface;final class DoctrineArenaPerformanceRecorder implements ArenaPerformanceRecorderInterface{public function __construct(private readonly EntityManagerInterface $em){}public function record(string $duelId,int $position):void{$q=$this->em->find(DuelQuestionRecord::class,['duelId'=>$duelId,'position'=>$position]);if(!$q instanceof DuelQuestionRecord)return;foreach($this->em->getRepository(DuelAnswerRecord::class)->findBy(['duelId'=>$duelId,'position'=>$position]) as $a){$existing=$this->em->getRepository(AttemptRecord::class)->findOneBy(['arenaDuelId'=>$duelId,'userId'=>$a->userId,'questionId'=>$q->questionId]);if($existing instanceof AttemptRecord)continue;$attempt=new AttemptRecord();$attempt->id=$this->uuid();$attempt->userId=$a->userId;$attempt->notebookId=null;$attempt->arenaDuelId=$duelId;$attempt->questionId=$q->questionId;$attempt->number=1;$attempt->context='ARENA_DUELO';$attempt->startedAt=$a->receivedAt;$attempt->completedAt=$a->receivedAt;$attempt->finalAnswerId=$a->id;$attempt->createdAt=$a->receivedAt;$answer=new AnswerRecord();$answer->id=$a->id;$answer->attemptId=$attempt->id;$answer->optionId=$a->optionId;$answer->sequence=1;$answer->elapsedSeconds=(int)floor($a->elapsedMilliseconds/1000);$answer->submittedAt=$a->receivedAt;$answer->createdAt=$a->receivedAt;$this->em->persist($attempt);$this->em->persist($answer);}}private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
